<?php
function nexora_render_section(array $s,int $i,array $settings): void {
 $type=$s['section_type']??'text';$data=json_decode((string)($s['section_data']??'{}'),true);if(!is_array($data))$data=[];$mobile=json_decode((string)($s['mobile_data']??'{}'),true);if(!is_array($mobile))$mobile=[];
 $titleSize=max(20,min(100,(int)($data['title_size']??($settings['section_title_size_'.(int)$s['id']]??60))));$mobileTitle=max(18,min(64,(int)($mobile['title_size']??34)));$pt=max(0,min(240,(int)($s['padding_top']??80)));$pb=max(0,min(240,(int)($s['padding_bottom']??80)));$mpt=max(0,min(120,(int)($mobile['padding_top']??40)));$mpb=max(0,min(120,(int)($mobile['padding_bottom']??40)));$cols=max(1,min(3,(int)($mobile['columns']??1)));
 $c1=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($data['gradient_color_1']??''))?$data['gradient_color_1']:((preg_match('/^#[0-9a-fA-F]{6}$/',(string)($s['background_color']??''))?$s['background_color']:'#f6f7fb'));$c2=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($data['gradient_color_2']??''))?$data['gradient_color_2']:'#e8edf5'; if(strtolower($c1)==='#090909' && strtolower($c2)==='#262626' && empty($data['keep_legacy_dark_gradient'])){$c1='#f6f7fb';$c2='#e8edf5';}$c3=(!empty($data['use_gradient_color_3']) && preg_match('/^#[0-9a-fA-F]{6}$/',(string)($data['gradient_color_3']??'')))?$data['gradient_color_3']:'';$angle=max(0,min(360,(int)($data['gradient_angle']??135)));$gradient=(($data['gradient_type']??'linear')==='radial')?'radial-gradient(circle at 30% 30%, '.$c1.', '.$c2.($c3!==''?', '.$c3:'').')':'linear-gradient('.$angle.'deg, '.$c1.', '.$c2.($c3!==''?', '.$c3:'').')';
 $key=htmlspecialchars((string)$s['section_key'],ENT_QUOTES,'UTF-8');$title=htmlspecialchars((string)$s['title'],ENT_QUOTES,'UTF-8');$eyebrow=htmlspecialchars((string)($s['eyebrow']??''),ENT_QUOTES,'UTF-8');$body=nl2br(htmlspecialchars((string)($s['body']??''),ENT_QUOTES,'UTF-8'));$items=$data['items']??[];$mediaPath=trim((string)($s['image_path']??''));$mediaType=$data['media_type']??'image';$mediaSide=($data['media_side']??'left')==='right'?'right':'left';
 echo '<section id="'.$key.'" class="section nx-section nx-type-'.htmlspecialchars((string)$type,ENT_QUOTES,'UTF-8').' '.($s['section_key']==='hero'?'hero':'').' nx-media-'.$mediaSide.'" style="--section-title-size:'.$titleSize.'px;--nx-mobile-title:'.$mobileTitle.'px;--nx-pad-top:'.$pt.'px;--nx-pad-bottom:'.$pb.'px;--nx-m-pad-top:'.$mpt.'px;--nx-m-pad-bottom:'.$mpb.'px;--nx-mobile-cols:'.$cols.';background:'.$gradient.';">';
 echo '<div class="nx-section-layout"><div class="section-inner reveal"><p class="eyebrow">'.$eyebrow.'</p><h1>'.$title.'</h1>'.($body!==''?'<p class="lead">'.$body.'</p>':'');
 if(in_array($type,['services','cards','gallery','stats','testimonials','faq'],true)&&is_array($items)&&$items){echo '<div class="nx-items">';foreach($items as $line){$parts=explode('|',(string)$line);$a=htmlspecialchars(trim($parts[0]??''),ENT_QUOTES,'UTF-8');$b=htmlspecialchars(trim($parts[1]??''),ENT_QUOTES,'UTF-8');$c=trim($parts[2]??'');echo '<article class="nx-item">';if($type==='stats')echo '<strong class="nx-stat">'.$a.'</strong>';elseif($type==='gallery'&&$c!=='')echo '<img loading="lazy" src="'.htmlspecialchars($c,ENT_QUOTES,'UTF-8').'" alt="'.$a.'">';else echo '<h3>'.$a.'</h3>';if($b!=='')echo '<p>'.$b.'</p>';if($type==='testimonials'&&$c!=='')echo '<small>'.htmlspecialchars($c,ENT_QUOTES,'UTF-8').'</small>';echo '</article>'; }echo '</div>';}
 if($type==='html'&&!empty($s['custom_html']))echo '<div class="nx-custom-html">'.$s['custom_html'].'</div>';
 if($type==='contact')echo '<form class="nx-contact-form" method="post" action="contact-submit.php"><label>نام<input name="name" required maxlength="120"></label><label>ایمیل<input type="email" name="email" required maxlength="190"></label><label>پیام<textarea name="message" required maxlength="5000"></textarea></label><button class="button" type="submit">ارسال پیام</button></form>';
 if(!empty($s['button_text']))echo '<a class="button" href="'.htmlspecialchars((string)($s['button_url']?:'#contact'),ENT_QUOTES,'UTF-8').'">'.htmlspecialchars((string)$s['button_text'],ENT_QUOTES,'UTF-8').' ↗</a>';
 if($s['section_key']==='hero'){ if($mediaPath!==''){ echo '<div class="hero-visual hero-visual-custom">'; if($mediaType==='video'){echo '<video controls playsinline preload="metadata" src="'.htmlspecialchars($mediaPath,ENT_QUOTES,'UTF-8').'"></video>';} elseif($mediaType==='embed'){ $heroEmbed=''; if(preg_match('~(?:youtube\.com/(?:watch\?v=|shorts/|embed/)|youtu\.be/)([A-Za-z0-9_-]{6,})~i',$mediaPath,$hm))$heroEmbed='https://www.youtube-nocookie.com/embed/'.$hm[1]; elseif(preg_match('~aparat\.com/(?:v/|video/video/embed/videohash/)([A-Za-z0-9_-]+)~i',$mediaPath,$hm))$heroEmbed='https://www.aparat.com/video/video/embed/videohash/'.$hm[1]; elseif(preg_match('~player\.vimeo\.com/video/[0-9]+~i',$mediaPath))$heroEmbed=$mediaPath; if($heroEmbed!=='')echo '<iframe loading="lazy" src="'.htmlspecialchars($heroEmbed,ENT_QUOTES,'UTF-8').'" title="'.$title.'" allowfullscreen></iframe>'; else echo '<p>لینک ویدیو معتبر نیست.</p>'; } else {echo '<img loading="lazy" src="'.htmlspecialchars($mediaPath,ENT_QUOTES,'UTF-8').'" alt="'.$title.'">';} echo '</div>'; } else {echo '<div class="hero-visual"><div class="orb orb-one"></div><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="visual-label">DIGITAL / DESIGN / STRATEGY</div></div>'; }}
 echo '</div>';
 if($mediaPath!=='' && $s['section_key']!=='hero') { echo '<div class="nx-section-media">'; if($mediaType==='video'){echo '<video controls playsinline preload="metadata" src="'.htmlspecialchars($mediaPath,ENT_QUOTES,'UTF-8').'"></video>';}elseif($mediaType==='embed'){ $embedUrl=''; if(preg_match('~(?:youtube\.com/(?:watch\?v=|shorts/|embed/)|youtu\.be/)([A-Za-z0-9_-]{6,})~i',$mediaPath,$m))$embedUrl='https://www.youtube-nocookie.com/embed/'.$m[1]; elseif(preg_match('~aparat\.com/(?:v/|video/video/embed/videohash/)([A-Za-z0-9_-]+)~i',$mediaPath,$m))$embedUrl='https://www.aparat.com/video/video/embed/videohash/'.$m[1]; elseif(preg_match('~player\.vimeo\.com/video/[0-9]+~i',$mediaPath))$embedUrl=$mediaPath; elseif(preg_match('~^https://(www\.)?(youtube-nocookie\.com/embed/|youtube\.com/embed/|www\.aparat\.com/video/video/embed/videohash/|player\.vimeo\.com/video/)~i',$mediaPath))$embedUrl=$mediaPath; if($embedUrl!=='')echo '<iframe loading="lazy" src="'.htmlspecialchars($embedUrl,ENT_QUOTES,'UTF-8').'" title="'.$title.'" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>'; else echo '<p>لینک ویدیو معتبر نیست.</p>'; }else{echo '<img loading="lazy" src="'.htmlspecialchars($mediaPath,ENT_QUOTES,'UTF-8').'" alt="'.$title.'">';}echo '</div>'; }
 echo '</div><span class="section-number">'.sprintf('%02d',$i+1).'</span></section>';
}
